INSERT INTO page_translations (page_id, locale, title, excerpt, content, seo_title, seo_keywords, seo_description) VALUES
(1, 'en', 'About Us', 'PLANET AVIATION, S.L. is a globally recognized General Sales & Service Agent headquartered in Europe.', '<p>PLANET AVIATION, S.L. is a globally recognized General Sales & Service Agent (GSSA) headquartered in Europe, dedicated to bridging the gap between complex logistics needs and streamlined execution. We pride ourselves on delivering tailor-made, highly specialized solutions that empower our customers to navigate the ever-evolving aviation landscape with confidence.</p><p>We are redefining GSSA expertise through a four-pillar strategy: Commercialization, Technology, Solutions, and Sustainability. By leveraging our extensive local market knowledge, we enable freight forwarders to maximize their operational performance and achieve superior commercial results.</p><p>Recognizing that air service is the backbone of global supply chain security, we go beyond standard logistics. Planet Aviation offers comprehensive cargo insurance packages designed to provide robust risk prevention and loss compensation.</p>', 'About Planet Aviation', 'aviation, gssa, logistics', 'Learn more about Planet Aviation.'),
(1, 'es', 'About Us', 'PLANET AVIATION, S.L. is a globally recognized General Sales & Service Agent headquartered in Europe.', '<p>PLANET AVIATION, S.L. is a globally recognized General Sales & Service Agent (GSSA) headquartered in Europe, dedicated to bridging the gap between complex logistics needs and streamlined execution.</p>', 'About Planet Aviation', 'aviation, gssa, logistics', 'Learn more about Planet Aviation.'),
(2, 'en', 'Contact Us', 'If you need further information about our services, please fill out the form below. Our team of logistics experts will get in touch with you as soon as possible.', '<p>Share your schedule, routing, or document needs and our operations team will reply quickly.</p>', 'Contact Planet Aviation', 'contact, aviation', 'Reach the Planet Aviation team.'),
(2, 'es', 'Contact Us', 'If you need further information about our services, please fill out the form below. Our team of logistics experts will get in touch with you as soon as possible.', '<p>Share your schedule, routing, or document needs and our operations team will reply quickly.</p>', 'Contact Planet Aviation', 'contact, aviation', 'Reach the Planet Aviation team.');
