INSERT INTO service_translations (service_id, locale, title, summary, content, seo_title, seo_keywords, seo_description) VALUES
(1, 'en', 'General Sales & Service Agent', 'Specializing in air freight operations across Europe, Asia, Middle East and Latin America.', '<ul><li>Delivered 1,200,000+ tons of cargo worldwide</li><li>Dynamic capacity allocation for maximum yield optimization</li><li>Consistent achievement and surpassing of airline sales targets</li></ul>', 'General Sales & Service Agent', 'gssa, cargo sales', 'Full GSSA representation for airline principals.'),
(1, 'es', 'General Sales & Service Agent', 'Specializing in air freight operations across Europe, Asia, Middle East and Latin America.', '<ul><li>Delivered 1,200,000+ tons of cargo worldwide</li><li>Dynamic capacity allocation for maximum yield optimization</li><li>Consistent achievement and surpassing of airline sales targets</li></ul>', 'General Sales & Service Agent', 'gssa, cargo sales', 'Full GSSA representation for airline principals.'),
(2, 'en', 'Air Cargo Consolidation Experts', 'Strategic capacity optimization and rapid consolidation solutions.', '<ul><li>Strategic Capacity Optimization: maximizing cubic yield</li><li>Precise Capacity Management: effective route utilization</li><li>Dynamic Payload Adjustments: real-time flexibility</li><li>Rapid Air Consolidation Solutions: fast turnaround groupings</li></ul>', 'Air Cargo Consolidation Experts', 'air cargo, consolidation', 'Cargo consolidation and capacity management.'),
(2, 'es', 'Air Cargo Consolidation Experts', 'Strategic capacity optimization and rapid consolidation solutions.', '<ul><li>Strategic Capacity Optimization: maximizing cubic yield</li><li>Precise Capacity Management: effective route utilization</li><li>Dynamic Payload Adjustments: real-time flexibility</li><li>Rapid Air Consolidation Solutions: fast turnaround groupings</li></ul>', 'Air Cargo Consolidation Experts', 'air cargo, consolidation', 'Cargo consolidation and capacity management.'),
(3, 'en', 'Handling & Trucking', 'Strong ground handling with superior service and cost-effective trucking.', '<ul><li>Strong ground handling with superior service</li><li>Cost-effective handling and trucking solutions</li><li>Import handling and administration services</li></ul>', 'Handling & Trucking', 'handling, trucking', 'Ground handling and trucking services.'),
(3, 'es', 'Handling & Trucking', 'Strong ground handling with superior service and cost-effective trucking.', '<ul><li>Strong ground handling with superior service</li><li>Cost-effective handling and trucking solutions</li><li>Import handling and administration services</li></ul>', 'Handling & Trucking', 'handling, trucking', 'Ground handling and trucking services.'),
(4, 'en', 'Insurance Solutions', 'Comprehensive cargo insurance solutions for airline and logistics partners.', '<ul><li>Comprehensive Global Coverage</li><li>Flexible Policy Options for all shipment types</li><li>Fast Track Claims Processing</li></ul>', 'Insurance Solutions', 'insurance, cargo insurance', 'Cargo insurance products for logistics partners.'),
(4, 'es', 'Insurance Solutions', 'Comprehensive cargo insurance solutions for airline and logistics partners.', '<ul><li>Comprehensive Global Coverage</li><li>Flexible Policy Options for all shipment types</li><li>Fast Track Claims Processing</li></ul>', 'Insurance Solutions', 'insurance, cargo insurance', 'Cargo insurance products for logistics partners.');
