INSERT INTO post_translations (post_id, locale, title, excerpt, content, seo_title, seo_keywords, seo_description) VALUES
(1, 'en', 'Planet Aviation expands regional network support', 'A new operating framework improves coordination speed for partner operators.', '<p>Planet Aviation has expanded its regional operating network to streamline support requests and improve partner visibility across active missions.</p>', 'Planet Aviation News', 'aviation news', 'Regional network support update.'),
(1, 'es', 'Planet Aviation expands regional network support', 'A new operating framework improves coordination speed for partner operators.', '<p>Planet Aviation has expanded its regional operating network to streamline support requests and improve partner visibility across active missions.</p>', 'Planet Aviation News', 'aviation news', 'Regional network support update.'),
(2, 'en', 'Air Cargo Market Analysis 2026: The Shift', 'A fresh market analysis highlights the lane shifts shaping current cargo demand.', '<p>New market data shows sharper demand movement across regional cargo corridors, pushing operators toward more dynamic consolidation and pricing strategies.</p>', 'Air Cargo Market Analysis', 'market analysis, cargo', 'Air cargo market analysis.'),
(2, 'es', 'Air Cargo Market Analysis 2026: The Shift', 'A fresh market analysis highlights the lane shifts shaping current cargo demand.', '<p>New market data shows sharper demand movement across regional cargo corridors, pushing operators toward more dynamic consolidation and pricing strategies.</p>', 'Air Cargo Market Analysis', 'market analysis, cargo', 'Air cargo market analysis.'),
(3, 'en', 'Transport Logistic & Air Cargo Europe 2025', 'Highlights from one of the leading logistics and air cargo trade events.', '<p>Planet Aviation reviews the operating trends, carrier strategies, and partner conversations emerging from this year''s major air cargo event.</p>', 'Transport Logistic Europe', 'transport logistic, air cargo', 'Event highlights from Europe.'),
(3, 'es', 'Transport Logistic & Air Cargo Europe 2025', 'Highlights from one of the leading logistics and air cargo trade events.', '<p>Planet Aviation reviews the operating trends, carrier strategies, and partner conversations emerging from this year''s major air cargo event.</p>', 'Transport Logistic Europe', 'transport logistic, air cargo', 'Event highlights from Europe.'),
(4, 'en', 'New documentation checklist for summer operations', 'A standard document pack is now recommended for charter support requests.', '<p>The operations team recommends a standard documentation checklist covering permits, handler coordination, passenger manifests, and airport slots for summer operations.</p>', 'Operations Checklist', 'operations checklist', 'Document checklist update.'),
(4, 'es', 'New documentation checklist for summer operations', 'A standard document pack is now recommended for charter support requests.', '<p>The operations team recommends a standard documentation checklist covering permits, handler coordination, passenger manifests, and airport slots for summer operations.</p>', 'Operations Checklist', 'operations checklist', 'Document checklist update.');
